mapper.delete:
DELETE FROM tb_department
WHERE department_id = #{departmentId}
  AND tenant_id     = #{tenantId}

mapper.update:
UPDATE tb_department
SET
    use_at     = #{useAt},
    updated_at = CURRENT_TIMESTAMP
WHERE department_id = #{departmentId}
  AND tenant_id     = #{tenantId}

mapper.select:
SELECT COUNT(*)
FROM tb_department
WHERE parent_department_id = #{departmentId}
  AND tenant_id            = #{tenantId}
